// === Tab: mySketch ===
let isMobile = /iPhone|iPod|Android/i.test(navigator.userAgent);
let repel_radius, radius_;
let angle = 0;
let points = [];
const particles = 10000;
const attraction = 0.008;
const damping = 0.8;
const repel_strength = 33;

// Animation & UI Control
let modeSelect, saveBtn, saveAlphaBtn, resetBtn, invertBtn;
let startTime;
let font;
let textPointsA = [];
let textPointsB = [];
let isInverted = false; 

function preload() {
    font = loadFont('https://cdnjs.cloudflare.com/ajax/libs/ink/3.1.10/fonts/Roboto/roboto-regular-webfont.ttf');
}

function setup() {
    let canvasSize = isMobile ? [360, 360] : [900, 700];
    createCanvas(canvasSize[0], canvasSize[1]);

    radius_ = isMobile ? 160 : 250;
    repel_radius = isMobile ? 60 : 90;
    startTime = millis();

    // --- UI ELEMENTS ---
    let uiY = 10;

    modeSelect = createSelect();
    modeSelect.position(10, uiY);
    modeSelect.option('Text Morph', 'text');
    modeSelect.option('Geometry Morph', 'geometry');

    invertBtn = createButton('Invert');
    invertBtn.position(140, uiY);
    invertBtn.mousePressed(() => isInverted = !isInverted);

    saveBtn = createButton('Save (Solid)');
    saveBtn.position(200, uiY);
    saveBtn.mousePressed(() => saveArt(false));

    saveAlphaBtn = createButton('Save (Transparent)');
    saveAlphaBtn.position(295, uiY);
    saveAlphaBtn.mousePressed(() => saveArt(true));

    resetBtn = createButton('Restart');
    resetBtn.position(430, uiY);
    resetBtn.mousePressed(() => startTime = millis());

    pixelDensity(1); 
    strokeWeight(0.8);

    // Pre-calculate text points
    let fontSize = isMobile ? 80 : 150;

	let boundsA = font.textBounds('SLOW', 0, 0, fontSize);
			textPointsA = font.textToPoints('SLOW', -boundsA.w / 2, boundsA.h / 2, fontSize, { sampleFactor: 0.1 });

	let boundsB = font.textBounds('MOTION', 0, 0, fontSize);
			textPointsB = font.textToPoints('MOTION', -boundsB.w / 2, boundsB.h / 2, fontSize, { sampleFactor: 0.2 });

    for (let i = 0; i < particles; i++) {
        points.push({
            index: i,
            pos: createVector(0, 0),
            vel: createVector(0, 0)
        });
    }
}

function draw() {
    // 1. Clear the canvas every frame to allow transparency
    clear(); 

    // 2. Draw a background ONLY if we aren't "in the middle" of a transparent save
    // (p5.js draws the background on top of the 'clear' area)
    if (isInverted) {
        background(255);
        stroke(0);
    } else {
        background(0);
        stroke(255);
    }

    translate(width / 2, height / 2);

	 let cycleDuration = 7000
    let elapsed = (millis() - startTime) % (cycleDuration * 2);
	 let showA = elapsed < cycleDuration;
    let currentMode = modeSelect.value();
    let mouse = createVector((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) - width / 2, (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))) - height / 2);

    for (let p of points) {
        let i = p.index;
        let home;

        if (currentMode === "geometry") {
            home = showA ? getSpherePos(i) : getRectPos(i);
        } else {
            home = showA ? getTextPos(i, textPointsA) : getTextPos(i, textPointsB);
        }

        let toHome = p5.Vector.sub(home, p.pos);
        p.vel.add(toHome.mult(attraction));

        let away = p5.Vector.sub(p.pos, mouse);
        let d2 = away.magSq();
        if (d2 > 0.1 && d2 < repel_radius * repel_radius) {
            away.setMag(repel_strength * (1 - sqrt(d2) / repel_radius));
            p.vel.add(away);
        }

        p.vel.mult(damping);
        p.pos.add(p.vel);
        line(p.pos.x, p.pos.y, p.pos.x + p.vel.x * 4, p.pos.y + p.vel.y * 6);
    }
    angle += 0.01;
}

// Special Save Function
function saveArt(transparent) {
    if (transparent) {
        // Redraw one frame without the background call
        clear();
        // Keep the stroke color based on current mode so points are visible
        stroke(isInverted ? 0 : 255);

        // Note: We don't need to loop the points here because saveCanvas 
        // will capture the very next render cycle. 
        // We force a quick re-render without background:
        background(0, 0); // Sets an alpha-0 background (fully transparent)
        saveCanvas('intensum_transparent', 'png');
    } else {
        let suffix = isInverted ? "_light" : "_dark";
        saveCanvas('intensum_solid' + suffix, 'png');
    }
}

// --- Position Helpers ---
function getSpherePos(i) {
    return createVector(sin(i + angle) * sin(i * i) * radius_, cos(i * i) * radius_);
}

function getRectPos(i) {
    let rectW = radius_ * 1.5;
    let rectH = radius_;
    let x = (i % 100) / 100 * rectW - rectW / 2;
    let y = floor(i / 100) / (particles / 100) * rectH - rectH / 2;
    return createVector(x, y);
}

function getTextPos(i, array) {
    let p = array[i % array.length];
    return createVector(p.x, p.y);
}

